mapper.select:
select t.id, ifnull(t.company_id,es.clinic_id) as orgId, t.user_id as userId, t.vacation_id as vacationId, if(vs.vacation_status=1,t.start_time,ifnull(es.work_date,t.start_time)) as startDate, t.end_time as endDate, ls.start_time as startTime, ls.end_time as endTime, t.leave_reason as leaveReason, t.leave_picture as leavePicture, t.approval_now_people_id as approvalNowPeopleId, t.approval_criteria_id as approvalCriteriaId, t.approval_status as approvalStatus, vs.vacation_status as vacationStatus, ls.schedule_id as scheduleId from leave_info t left join vacation_set vs on t.vacation_id=vs.id left join leave_schedule ls on t.id=ls.leave_id left join employee_schedule es on es.id=ls.schedule_id
vs.vacation_enable=1
and t.approval_status = #{queryForm.approvalStatus}
and t.user_id = #{queryForm.userId}
and (DATE_FORMAT(t.start_time,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenStartDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andStartDate},'%Y-%m-%d') or DATE_FORMAT(es.work_date,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenStartDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andStartDate},'%Y-%m-%d'))
and vs.vacation_status = #{queryForm.vacationStatus}
order by t.start_time asc

select t.id, t.user_id as userId, t.vacation_id as vacationId, es.work_date as startDate, t.end_time as endDate, ls.start_time as startTime, ls.end_time as endTime, t.leave_reason as leaveReason, t.leave_picture as leavePicture, t.approval_now_people_id as approvalNowPeopleId, t.approval_criteria_id as approvalCriteriaId, t.approval_status as approvalStatus, vs.vacation_status as vacationStatus, ls.schedule_id as scheduleId from leave_info t left join vacation_set vs on t.vacation_id=vs.id left join leave_schedule ls on t.id=ls.leave_id left join employee_schedule es on es.id=ls.schedule_id
vs.vacation_status=0 and vs.vacation_enable=1
and t.approval_status = #{queryForm.approvalStatus}
and t.user_id = #{queryForm.userId}
and DATE_FORMAT(es.work_date,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenStartDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andStartDate},'%Y-%m-%d')
and vs.vacation_status = #{queryForm.vacationStatus}
order by t.start_time asc

select t.id, t.user_id as userId, t.company_id as orgId, t.vacation_id as vacationId, t.start_time as startDate, t.end_time as endDate, t.leave_reason as leaveReason, t.leave_picture as leavePicture, t.approval_now_people_id as approvalNowPeopleId, t.approval_criteria_id as approvalCriteriaId, t.approval_status as approvalStatus, vs.vacation_status as vacationStatus, vs.vacation_name as vacationName, t.crt_time as crtTime from leave_info t left join vacation_set vs on t.vacation_id=vs.id
t.approval_status = 1 and vs.vacation_enable=1
and t.company_id = #{queryForm.orgId}
and t.user_id = #{queryForm.userId}
and DATE_FORMAT(t.start_time,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenStartDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andStartDate},'%Y-%m-%d')
and vs.vacation_status = #{queryForm.vacationStatus}
or t.id in
#{item}
order by t.start_time asc

select DISTINCT es.id id, es.work_date date,es.clinic_id companyId,bs.first_start_time
startTime,IFNULL(bs.second_end_time,bs.first_end_time) endTime ,bs.type emType,bs.`name` emName,ls.start_time as leaveStartTime,ls.end_time as leaveEndTime
from employee_schedule es
LEFT JOIN base_schedule bs on es.schedule_id = bs.id
LEFT JOIN leave_schedule ls on ls.schedule_id = es.id


        and  bs.type = '上班'


        and es.work_date BETWEEN #{startTime} and #{endTime}


        and es.employee_id = #{userId}


        and ls.leave_id = #{id}


order by es.work_date

select DISTINCT a.* from (SELECT DISTINCT t.id, t.user_id AS userId, t.vacation_id AS vacationId, t.company_id AS companyId, vs.vacation_name AS vacationName, t.start_time AS startTime, t.end_time AS endTime, t.leave_reason AS leaveReason, t.leave_picture AS leavePicture, t.approval_criteria_id AS approvalCriteriaId, t.approval_status AS approvalStatus, t.crt_time AS crtTime, t.refuse_reason AS refuseReason, vs.vacation_status AS vacationStatus, IFNULL( sum( TIMESTAMPDIFF( MINUTE, ls.start_time, ls.end_time ) ), TIMESTAMPDIFF( MINUTE, t.start_time, DATE_ADD(t.end_time, INTERVAL '1' DAY) ) / 3 ) AS leaveTime FROM leave_info t LEFT JOIN vacation_set vs ON t.vacation_id = vs.id LEFT JOIN leave_schedule ls ON ls.leave_id = t.id
and t.id = #{id}
and t.user_id = #{userId}
and t.crt_time >= #{startTime} and t.crt_time <= #{endTime}
GROUP BY t.id) a LEFT JOIN copy_info ci ON ci.apply_id = a.id and ci.apply_type = 0
and ci.user_id = #{copyId}
order by a.crtTime desc

select DISTINCT a.* from (SELECT DISTINCT t.id, t.user_id AS userId, t.vacation_id AS vacationId, t.company_id AS companyId, vs.vacation_name AS vacationName, t.start_time AS startTime, t.end_time AS endTime, t.leave_reason AS leaveReason, t.leave_picture AS leavePicture, t.approval_criteria_id AS approvalCriteriaId, t.approval_status AS approvalStatus, t.crt_time AS crtTime, t.refuse_reason AS refuseReason, vs.vacation_status AS vacationStatus, IFNULL( sum( TIMESTAMPDIFF( MINUTE, ls.start_time, ls.end_time ) ), TIMESTAMPDIFF( MINUTE, t.start_time, DATE_ADD(t.end_time, INTERVAL '1' DAY) ) / 3 ) AS leaveTime FROM leave_info t LEFT JOIN vacation_set vs ON t.vacation_id = vs.id LEFT JOIN leave_schedule ls ON ls.leave_id = t.id
and t.user_id in
#{userid}
and t.id = #{id}
and t.start_time >= #{startTime} and t.start_time < DATE_ADD(#{endTime}, INTERVAL '1' DAY)
GROUP BY t.id) a LEFT JOIN copy_info ci ON ci.apply_id = a.id and ci.apply_type = 0
and ci.user_id = #{copyId}
order by a.crtTime desc

select vs.vacation_status from vacation_set vs
LEFT JOIN leave_info li on li.vacation_id = vs.id
where li.id = #{id}

select DISTINCT a.* from (SELECT DISTINCT t.id, t.user_id AS userId, t.vacation_id AS vacationId, t.company_id AS companyId, vs.vacation_name AS vacationName, t.start_time AS startTime, t.end_time AS endTime, t.leave_reason AS leaveReason, t.leave_picture AS leavePicture, t.approval_criteria_id AS approvalCriteriaId, t.approval_status AS approvalStatus, t.crt_time AS crtTime, t.refuse_reason AS refuseReason, vs.vacation_status AS vacationStatus, IFNULL( sum( TIMESTAMPDIFF( MINUTE, ls.start_time, ls.end_time ) ), TIMESTAMPDIFF( MINUTE, t.start_time, DATE_ADD(t.end_time, INTERVAL '1' DAY) ) / 3 ) AS leaveTime, ls.start_time AS LsStartDate, ls.end_time AS LsEndDate FROM leave_info t LEFT JOIN vacation_set vs ON t.vacation_id = vs.id LEFT JOIN leave_schedule ls ON ls.leave_id = t.id
and t.user_id in
#{userid}
and t.id = #{id}
and t.approval_status = #{approvalStatus}
and ( (t.start_time <= #{startTime} and t.end_time >= #{startTime}) or (t.start_time <= #{endTime} and t.end_time >= #{endTime}) or (t.start_time >= #{startTime} and t.start_time <= #{endTime}) or (t.end_time>= #{startTime} and t.end_time <= #{endTime}) )
GROUP BY t.id,ls.start_time,ls.end_time) a LEFT JOIN copy_info ci ON ci.apply_id = a.id and ci.apply_type = 0
and ci.user_id = #{copyId}
order by a.crtTime desc
